+export function createSingleflightCache({
+  ttlMs,
+  staleWhileRevalidateMs = 0,
+  maxEntries = 128,
+  maxRetries = 0,
+  baseRetryDelayMs = 20,
+  now = () => Date.now(),
+  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
+}) {
+  const entries = new Map();
+  const flights = new Map();
+  const counters = { hits: 0, staleHits: 0, misses: 0, coalesced: 0, evictions: 0 };
+
+  const abortError = () => new DOMException('This operation was aborted', 'AbortError');
+
+  function store(key, value) {
+    entries.delete(key);
+    entries.set(key, { value, storedAt: now() });
+    while (entries.size > maxEntries) {
+      entries.delete(entries.keys().next().value);
+      counters.evictions++;
+    }
+  }
+
+  async function run(flight) {
+    const { key, controller } = flight;
+    try {
+      for (let attempt = 0; ; attempt++) {
+        try {
+          if (controller.signal.aborted) throw abortError();
+          const value = await flight.loader({ signal: controller.signal });
+          if (!controller.signal.aborted && (flight.detached || flight.waiters > 0) && flights.get(key) === flight) {
+            store(key, value);
+          }
+          return value;
+        } catch (error) {
+          if (error?.name === 'AbortError' || controller.signal.aborted || attempt >= maxRetries) {
+            throw error;
+          }
+          await sleep(baseRetryDelayMs * (2 ** attempt));
+        }
+      }
+    } finally {
+      if (flights.get(key) === flight) flights.delete(key);
+    }
+  }
+
+  function start(key, loader, detached = false) {
+    const flight = {
+      key,
+      loader,
+      detached,
+      controller: new AbortController(),
+      waiters: 0,
+      promise: null,
+    };
+    flights.set(key, flight);
+    flight.promise = run(flight);
+    // A detached refresh, or a flight whose callers all abort, still needs a rejection handler.
+    flight.promise.catch(() => {});
+    return flight;
+  }
+
+  function wait(flight, signal) {
+    if (signal?.aborted) return Promise.reject(abortError());
+    flight.waiters++;
+    return new Promise((resolve, reject) => {
+      let finished = false;
+      const cleanup = () => {
+        finished = true;
+        signal?.removeEventListener('abort', onAbort);
+      };
+      const onAbort = () => {
+        if (finished) return;
+        cleanup();
+        flight.waiters--;
+        if (flight.waiters === 0) flight.controller.abort();
+        reject(abortError());
+      };
+      signal?.addEventListener('abort', onAbort, { once: true });
+      flight.promise.then(
+        (value) => {
+          if (finished) return;
+          cleanup();
+          resolve(value);
+        },
+        (error) => {
+          if (finished) return;
+          cleanup();
+          reject(error);
+        },
+      );
+    });
+  }
+
+  return {
+    async get(key, loader, { signal } = {}) {
+      if (signal?.aborted) throw abortError();
+
+      const entry = entries.get(key);
+      if (entry) {
+        const age = now() - entry.storedAt;
+        if (age < ttlMs) {
+          entries.delete(key);
+          entries.set(key, entry);
+          counters.hits++;
+          return entry.value;
+        }
+        if (age < ttlMs + staleWhileRevalidateMs) {
+          entries.delete(key);
+          entries.set(key, entry);
+          counters.staleHits++;
+          if (!flights.has(key)) start(key, loader, true);
+          return entry.value;
+        }
+        entries.delete(key);
+      }
+
+      const existing = flights.get(key);
+      if (existing) {
+        counters.coalesced++;
+        return wait(existing, signal);
+      }
+
+      counters.misses++;
+      return wait(start(key, loader), signal);
+    },
+
+    invalidate(key) {
+      entries.delete(key);
+    },
+
+    clear() {
+      entries.clear();
+    },
+
+    stats() {
+      return { size: entries.size, ...counters };
+    },
+  };
+}
