+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createSingleflightCache } from '../src/singleflight-cache.mjs';
+
+function deferred() {
+  let resolve;
+  let reject;
+  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
+  return { promise, resolve, reject };
+}
+
+function clock(start = 0) {
+  const api = {
+    time: start,
+    delays: [],
+    now: () => api.time,
+    sleep: async (ms) => { api.delays.push(ms); },
+  };
+  return api;
+}
+
+const flush = async () => {
+  await Promise.resolve();
+  await Promise.resolve();
+  await Promise.resolve();
+};
+
+const isAbort = (error) => error?.name === 'AbortError';
+
+test('fresh hits avoid loading, update recency, and use strict age boundary', async () => {
+  const time = clock();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 10, maxEntries: 2, now: () => time.time, sleep: time.sleep });
+  const load = async (value) => { calls++; return value; };
+
+  assert.equal(await cache.get('a', () => load('A')), 'A');
+  assert.equal(await cache.get('b', () => load('B')), 'B');
+  time.time = 9;
+  assert.equal(await cache.get('a', () => load('new')), 'A');
+  assert.deepEqual(cache.stats(), { size: 2, hits: 1, staleHits: 0, misses: 2, coalesced: 0, evictions: 0 });
+
+  await cache.get('c', () => load('C'));
+  assert.equal(cache.stats().evictions, 1, 'a hit made b least recently used');
+  assert.equal(await cache.get('a', () => load('bad')), 'A');
+  await cache.get('b', () => load('B2'));
+  assert.equal(calls, 4);
+
+  time.time = 19;
+  assert.equal(await cache.get('a', () => load('A2')), 'A2', 'age === ttl is not fresh');
+});
+
+test('stale hit returns immediately, deduplicates background refresh, and stores refreshed value', async () => {
+  const time = clock();
+  const refresh = deferred();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 10, staleWhileRevalidateMs: 20, now: () => time.time, sleep: time.sleep });
+  const loader = () => {
+    calls++;
+    return calls === 1 ? Promise.resolve('old') : refresh.promise;
+  };
+
+  assert.equal(await cache.get('k', loader), 'old');
+  time.time = 10;
+  assert.equal(await cache.get('k', loader), 'old');
+  assert.equal(await cache.get('k', loader), 'old');
+  assert.equal(calls, 2, 'only one background loader');
+  assert.deepEqual(cache.stats(), { size: 1, hits: 0, staleHits: 2, misses: 1, coalesced: 0, evictions: 0 });
+
+  refresh.resolve('new');
+  await flush();
+  assert.equal(await cache.get('k', loader), 'new');
+  assert.equal(calls, 2);
+});
+
+test('background refresh failure and exhausted retries keep stale value and never reject unhandled', async () => {
+  const time = clock();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 10, staleWhileRevalidateMs: 30, maxRetries: 2, baseRetryDelayMs: 3, now: () => time.time, sleep: time.sleep });
+  const loader = async () => {
+    calls++;
+    if (calls === 1) return 'stale';
+    throw new Error('offline');
+  };
+
+  await cache.get('k', loader);
+  time.time = 15;
+  assert.equal(await cache.get('k', loader), 'stale');
+  await flush();
+  assert.equal(calls, 4);
+  assert.deepEqual(time.delays, [3, 6]);
+  assert.equal(cache.stats().size, 1);
+
+  assert.equal(await cache.get('k', loader), 'stale', 'failed refresh was evicted, allowing a later refresh');
+  assert.equal(calls, 5);
+  await flush();
+  assert.equal(cache.stats().size, 1);
+});
+
+test('fully expired stale entry is not returned and refreshes in foreground', async () => {
+  const time = clock();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 5, staleWhileRevalidateMs: 5, now: () => time.time, sleep: time.sleep });
+  const loader = async () => ++calls;
+  assert.equal(await cache.get('k', loader), 1);
+  time.time = 10;
+  assert.equal(await cache.get('k', loader), 2);
+  assert.equal(cache.stats().staleHits, 0);
+  assert.equal(cache.stats().misses, 2);
+});
+
+test('concurrent misses coalesce and one caller abort does not abort shared loader', async () => {
+  const pending = deferred();
+  const controller = new AbortController();
+  let calls = 0;
+  let sharedSignal;
+  const cache = createSingleflightCache({ ttlMs: 100 });
+  const loader = ({ signal }) => { calls++; sharedSignal = signal; return pending.promise; };
+
+  const first = cache.get('k', loader, { signal: controller.signal });
+  const second = cache.get('k', loader);
+  const third = cache.get('k', loader);
+  controller.abort();
+  await assert.rejects(first, isAbort);
+  assert.equal(sharedSignal.aborted, false);
+  assert.equal(calls, 1);
+  assert.deepEqual(cache.stats(), { size: 0, hits: 0, staleHits: 0, misses: 1, coalesced: 2, evictions: 0 });
+
+  pending.resolve(42);
+  assert.equal(await second, 42);
+  assert.equal(await third, 42);
+  assert.equal(await cache.get('k', loader), 42);
+  assert.equal(calls, 1);
+});
+
+test('all callers aborting aborts loader, evicts flight, and permits a new load', async () => {
+  const a = new AbortController();
+  const b = new AbortController();
+  let calls = 0;
+  let sharedSignal;
+  const cache = createSingleflightCache({ ttlMs: 100 });
+  const loader = ({ signal }) => {
+    calls++;
+    sharedSignal = signal;
+    if (calls === 2) return Promise.resolve('next');
+    return new Promise((resolve, reject) => signal.addEventListener('abort', () => reject(new DOMException('stop', 'AbortError'))));
+  };
+
+  const first = cache.get('k', loader, { signal: a.signal });
+  const second = cache.get('k', loader, { signal: b.signal });
+  a.abort();
+  assert.equal(sharedSignal.aborted, false);
+  b.abort();
+  assert.equal(sharedSignal.aborted, true);
+  await assert.rejects(first, isAbort);
+  await assert.rejects(second, isAbort);
+  await flush();
+  assert.equal(cache.stats().size, 0);
+  assert.equal(await cache.get('k', loader), 'next');
+  assert.equal(calls, 2);
+});
+
+test('an all-aborted flight cannot cache a loader that ignores abortion', async () => {
+  const pending = deferred();
+  const controller = new AbortController();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 100 });
+  const loader = () => { calls++; return pending.promise; };
+  const result = cache.get('k', loader, { signal: controller.signal });
+  controller.abort();
+  await assert.rejects(result, isAbort);
+  pending.resolve('ignored');
+  await flush();
+  assert.equal(cache.stats().size, 0);
+  assert.equal(await cache.get('k', async () => { calls++; return 'fresh'; }), 'fresh');
+  assert.equal(calls, 2);
+});
+
+test('pre-aborted callers reject without hits, misses, or loader invocation', async () => {
+  const cache = createSingleflightCache({ ttlMs: 100 });
+  const controller = new AbortController();
+  controller.abort();
+  let calls = 0;
+  await assert.rejects(cache.get('k', async () => { calls++; }, { signal: controller.signal }), isAbort);
+  assert.equal(calls, 0);
+  assert.deepEqual(cache.stats(), { size: 0, hits: 0, staleHits: 0, misses: 0, coalesced: 0, evictions: 0 });
+});
+
+test('retries use exponential delays, then cache successful result', async () => {
+  const time = clock();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 100, maxRetries: 2, baseRetryDelayMs: 20, now: time.now, sleep: time.sleep });
+  const result = await cache.get('k', async () => {
+    calls++;
+    if (calls < 3) throw new Error(`fail ${calls}`);
+    return 'ok';
+  });
+  assert.equal(result, 'ok');
+  assert.equal(calls, 3);
+  assert.deepEqual(time.delays, [20, 40]);
+  assert.equal(await cache.get('k', async () => 'wrong'), 'ok');
+});
+
+test('retry exhaustion rejects every waiter, never caches error, and evicts flight', async () => {
+  const time = clock();
+  const failure = new Error('nope');
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 100, maxRetries: 1, baseRetryDelayMs: 7, now: time.now, sleep: time.sleep });
+  const loader = async () => { calls++; throw failure; };
+  const one = cache.get('k', loader);
+  const two = cache.get('k', loader);
+  await assert.rejects(one, (error) => error === failure);
+  await assert.rejects(two, (error) => error === failure);
+  assert.equal(calls, 2);
+  assert.deepEqual(time.delays, [7]);
+  assert.equal(cache.stats().size, 0);
+  await assert.rejects(cache.get('k', loader), (error) => error === failure);
+  assert.equal(calls, 4);
+});
+
+test('AbortError is not retried and is not cached', async () => {
+  const time = clock();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 100, maxRetries: 5, now: time.now, sleep: time.sleep });
+  await assert.rejects(cache.get('k', async () => { calls++; throw new DOMException('no', 'AbortError'); }), isAbort);
+  assert.equal(calls, 1);
+  assert.deepEqual(time.delays, []);
+  assert.equal(cache.stats().size, 0);
+  assert.equal(await cache.get('k', async () => 'ok'), 'ok');
+});
+
+test('abort during retry delay prevents another loader call', async () => {
+  const retry = deferred();
+  const controller = new AbortController();
+  let calls = 0;
+  let sharedSignal;
+  const cache = createSingleflightCache({ ttlMs: 100, maxRetries: 2, sleep: () => retry.promise });
+  const result = cache.get('k', async ({ signal }) => {
+    calls++;
+    sharedSignal = signal;
+    throw new Error('retry');
+  }, { signal: controller.signal });
+  await flush();
+  assert.equal(calls, 1);
+  controller.abort();
+  retry.resolve();
+  await assert.rejects(result, isAbort);
+  await flush();
+  assert.equal(calls, 1);
+  assert.equal(sharedSignal.aborted, true);
+});
+
+test('synchronous loader throws participate in retry and rejection', async () => {
+  const time = clock();
+  let calls = 0;
+  const cache = createSingleflightCache({ ttlMs: 1, maxRetries: 1, now: time.now, sleep: time.sleep });
+  await assert.rejects(cache.get('k', () => { calls++; throw new TypeError('sync'); }), TypeError);
+  assert.equal(calls, 2);
+  assert.deepEqual(time.delays, [20]);
+});
+
+test('capacity zero never retains entries and reports self-eviction', async () => {
+  const cache = createSingleflightCache({ ttlMs: 100, maxEntries: 0 });
+  assert.equal(await cache.get('k', async () => 'v'), 'v');
+  assert.deepEqual(cache.stats(), { size: 0, hits: 0, staleHits: 0, misses: 1, coalesced: 0, evictions: 1 });
+  assert.equal(await cache.get('k', async () => 'v2'), 'v2');
+});
+
+test('invalidate and clear remove values without resetting statistics or other keys', async () => {
+  const cache = createSingleflightCache({ ttlMs: 100 });
+  await cache.get('a', async () => 1);
+  await cache.get('b', async () => 2);
+  cache.invalidate('a');
+  cache.invalidate('missing');
+  assert.equal(cache.stats().size, 1);
+  assert.equal(await cache.get('a', async () => 3), 3);
+  cache.clear();
+  assert.equal(cache.stats().size, 0);
+  assert.equal(await cache.get('b', async () => 4), 4);
+  assert.deepEqual(cache.stats(), { size: 1, hits: 0, staleHits: 0, misses: 4, coalesced: 0, evictions: 0 });
+});
+
+test('keys and cached values use normal Map semantics, including undefined', async () => {
+  const cache = createSingleflightCache({ ttlMs: 100 });
+  const key = { id: 1 };
+  let calls = 0;
+  const loader = async () => { calls++; return undefined; };
+  assert.equal(await cache.get(key, loader), undefined);
+  assert.equal(await cache.get(key, loader), undefined);
+  assert.equal(calls, 1);
+  assert.equal(await cache.get({ id: 1 }, async () => 'different'), 'different');
+});

