+export function createSingleflightCache({
+  ttlMs,
+  staleWhileRevalidateMs = 0,
+  maxEntries = 128,
+  maxRetries = 0,
+  baseRetryDelayMs = 20,
+  now = () => Date.now(),
+  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
+}) {
+  const entries = new Map();
+  const flights = new Map();
+  const counters = { hits: 0, staleHits: 0, misses: 0, coalesced: 0, evictions: 0 };
+
+  const abortError = () => new DOMException('The operation was aborted', 'AbortError');
+
+  function store(key, value) {
+    if (maxEntries <= 0) return;
+    entries.delete(key);
+    entries.set(key, { value, time: now() });
+    while (entries.size > maxEntries) {
+      entries.delete(entries.keys().next().value);
+      counters.evictions++;
+    }
+  }
+
+  function delay(ms, signal) {
+    return new Promise((resolve, reject) => {
+      const onAbort = () => {
+        cleanup();
+        reject(abortError());
+      };
+      const cleanup = () => signal.removeEventListener('abort', onAbort);
+      signal.addEventListener('abort', onAbort, { once: true });
+      if (signal.aborted) {
+        onAbort();
+        return;
+      }
+      Promise.resolve(sleep(ms)).then(
+        () => { cleanup(); resolve(); },
+        (error) => { cleanup(); reject(error); },
+      );
+    });
+  }
+
+  function start(key, loader, background) {
+    const controller = new AbortController();
+    const flight = { controller, waiters: new Set(), background };
+    flights.set(key, flight);
+
+    const promise = (async () => {
+      for (let attempt = 0; ; attempt++) {
+        try {
+          const value = await loader({ signal: controller.signal });
+          if (controller.signal.aborted) throw abortError();
+          store(key, value);
+          return value;
+        } catch (error) {
+          if (error?.name === 'AbortError' || controller.signal.aborted || attempt >= maxRetries) {
+            throw error;
+          }
+          await delay(baseRetryDelayMs * (2 ** attempt), controller.signal);
+        }
+      }
+    })();
+
+    flight.promise = promise;
+    promise.catch(() => {}).finally(() => {
+      if (flights.get(key) === flight) flights.delete(key);
+    });
+    return flight;
+  }
+
+  function wait(flight, signal) {
+    return new Promise((resolve, reject) => {
+      const waiter = { reject };
+      flight.waiters.add(waiter);
+
+      const cleanup = () => {
+        signal?.removeEventListener('abort', onAbort);
+      };
+      const onAbort = () => {
+        if (!flight.waiters.delete(waiter)) return;
+        cleanup();
+        reject(abortError());
+        if (!flight.background && flight.waiters.size === 0) {
+          flight.controller.abort();
+        }
+      };
+
+      signal?.addEventListener('abort', onAbort, { once: true });
+      if (signal?.aborted) {
+        onAbort();
+        return;
+      }
+
+      const promise = flight.promise;
+      promise.then(
+        (value) => {
+          if (!flight.waiters.delete(waiter)) return;
+          cleanup();
+          resolve(value);
+        },
+        (error) => {
+          if (!flight.waiters.delete(waiter)) return;
+          cleanup();
+          reject(error);
+        },
+      );
+    });
+  }
+
+  async function get(key, loader, { signal } = {}) {
+    const entry = entries.get(key);
+    if (entry) {
+      const age = now() - entry.time;
+      if (age < ttlMs) {
+        entries.delete(key);
+        entries.set(key, entry);
+        counters.hits++;
+        return entry.value;
+      }
+      if (age < ttlMs + staleWhileRevalidateMs) {
+        entries.delete(key);
+        entries.set(key, entry);
+        counters.staleHits++;
+        if (!flights.has(key)) start(key, loader, true);
+        return entry.value;
+      }
+      entries.delete(key);
+    }
+
+    counters.misses++;
+    if (signal?.aborted) throw abortError();
+
+    let flight = flights.get(key);
+    if (flight?.controller.signal.aborted) flight = undefined;
+    if (flight) {
+      counters.coalesced++;
+    } else {
+      flight = start(key, loader, false);
+    }
+    return wait(flight, signal);
+  }
+
+  return {
+    get,
+    invalidate(key) {
+      return entries.delete(key);
+    },
+    clear() {
+      entries.clear();
+    },
+    stats() {
+      return { size: entries.size, ...counters };
+    },
+  };
+}
