+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createSingleflightCache } from '../src/singleflight-cache.mjs';
+
+const tick = () => new Promise((resolve) => setImmediate(resolve));
+const deferred = () => {
+  let resolve;
+  let reject;
+  const promise = new Promise((res, rej) => {
+    resolve = res;
+    reject = rej;
+  });
+  return { promise, resolve, reject };
+};
+const setup = (options = {}) => {
+  let time = 1_000;
+  const cache = createSingleflightCache({ ttlMs: 100, now: () => time, ...options });
+  return { cache, advance: (ms) => { time += ms; } };
+};
+
+test('fresh hits skip loader, update recency, and report stats', async () => {
+  const { cache, advance } = setup({ maxEntries: 2 });
+  let calls = 0;
+  const load = async (value) => { calls++; return value; };
+  assert.equal(await cache.get('a', () => load(1)), 1);
+  await cache.get('b', () => load(2));
+  advance(50);
+  assert.equal(await cache.get('a', () => load(3)), 1);
+  advance(49);
+  assert.equal(await cache.get('a', () => load(4)), 1);
+  assert.equal(calls, 2);
+  assert.deepEqual(cache.stats(), {
+    size: 2, hits: 2, staleHits: 0, misses: 2, coalesced: 0, evictions: 0,
+  });
+  await cache.get('c', () => load(5));
+  assert.equal(await cache.get('b', () => load(6)), 6);
+  assert.equal(calls, 4);
+  assert.equal(cache.stats().evictions, 2);
+});
