+const abortError = () => new DOMException('The operation was aborted', 'AbortError');
+const isAbortError = (error) => error?.name === 'AbortError';
+
+export function createSingleflightCache({
+  ttlMs,
+  staleWhileRevalidateMs = 0,
+  maxEntries = 128,
+  maxRetries = 0,
+  baseRetryDelayMs = 20,
+  now = () => Date.now(),
+  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
+}) {
+  const entries = new Map();
+  const flights = new Map();
+  const counters = { hits: 0, staleHits: 0, misses: 0, coalesced: 0, evictions: 0 };
+
+  function touch(key, entry) {
+    entries.delete(key);
+    entries.set(key, entry);
+  }
+
+  function store(key, value) {
+    if (maxEntries <= 0) return;
+    entries.delete(key);
+    while (entries.size >= maxEntries) {
+      entries.delete(entries.keys().next().value);
+      counters.evictions++;
+    }
+    if (maxEntries > 0) entries.set(key, { value, storedAt: now() });
+  }
+
+  async function sleepBeforeRetry(ms, signal) {
+    if (signal.aborted) throw abortError();
+    let onAbort;
+    const aborted = new Promise((_, reject) => {
+      onAbort = () => reject(abortError());
+      signal.addEventListener('abort', onAbort, { once: true });
+    });
+    try {
+      await Promise.race([Promise.resolve().then(() => sleep(ms)), aborted]);
+      if (signal.aborted) throw abortError();
+    } finally {
+      signal.removeEventListener('abort', onAbort);
+    }
+  }
+
+  function startFlight(key, loader, background = false) {
+    const controller = new AbortController();
+    const flight = { controller, waiters: 0, background, promise: null };
+
+    flight.promise = (async () => {
+      for (let attempt = 0; ; attempt++) {
+        try {
+          const value = await loader({ signal: controller.signal });
+          if (controller.signal.aborted) throw abortError();
+          store(key, value);
+          return value;
+        } catch (error) {
+          if (isAbortError(error) || attempt >= maxRetries) throw error;
+          await sleepBeforeRetry(baseRetryDelayMs * (2 ** attempt), controller.signal);
+        }
+      }
+    })().finally(() => {
+      if (flights.get(key) === flight) flights.delete(key);
+    });
+
+    flights.set(key, flight);
+    if (background) flight.promise.catch(() => {});
+    return flight;
+  }
+
+  function waitForFlight(flight, signal) {
+    flight.waiters++;
+    return new Promise((resolve, reject) => {
+      let settled = false;
+
+      const cleanup = () => signal?.removeEventListener('abort', onAbort);
+      const onAbort = () => {
+        if (settled) return;
+        settled = true;
+        cleanup();
+        flight.waiters--;
+        reject(abortError());
+        if (flight.waiters === 0) flight.controller.abort();
+      };
+      const settle = (callback, value) => {
+        if (settled) return;
+        settled = true;
+        cleanup();
+        callback(value);
+      };
+
+      signal?.addEventListener('abort', onAbort, { once: true });
+      flight.promise.then(
+        (value) => settle(resolve, value),
+        (error) => settle(reject, error),
+      );
+      if (signal?.aborted) onAbort();
+    });
+  }
+
+  return {
+    async get(key, loader, { signal } = {}) {
+      if (signal?.aborted) throw abortError();
+
+      const entry = entries.get(key);
+      const age = entry ? now() - entry.storedAt : 0;
+      if (entry && age < ttlMs) {
+        counters.hits++;
+        touch(key, entry);
+        return entry.value;
+      }
+      if (entry && age < ttlMs + staleWhileRevalidateMs) {
+        counters.staleHits++;
+        touch(key, entry);
+        if (!flights.has(key)) startFlight(key, loader, true);
+        return entry.value;
+      }
+
+      if (entry) entries.delete(key);
+      const existing = flights.get(key);
+      if (existing) {
+        counters.coalesced++;
+        return waitForFlight(existing, signal);
+      }
+
+      counters.misses++;
+      const flight = startFlight(key, loader);
+      return waitForFlight(flight, signal);
+    },
+
+    invalidate(key) {
+      return entries.delete(key);
+    },
+
+    clear() {
+      entries.clear();
+    },
+
+    stats() {
+      return { size: entries.size, ...counters };
+    },
+  };
+}
