+export function createSingleflightCache({
+  ttlMs,
+  staleWhileRevalidateMs = 0,
+  maxEntries = 128,
+  maxRetries = 0,
+  baseRetryDelayMs = 20,
+  now = () => Date.now(),
+  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
+}) {
+  const entries = new Map();
+  const flights = new Map();
+  const counters = { hits: 0, staleHits: 0, misses: 0, coalesced: 0, evictions: 0 };
+  const abortError = () => new DOMException("This operation was aborted", "AbortError");
+
+  function store(key, value) {
+    if (maxEntries <= 0) return;
+    entries.delete(key);
+    while (entries.size >= maxEntries) {
+      entries.delete(entries.keys().next().value);
+      counters.evictions++;
+    }
+    entries.set(key, { value, storedAt: now() });
+  }
+
+  function launch(key, loader) {
+    const controller = new AbortController();
+    const flight = { controller, waiters: 0 };
+    flight.promise = (async () => {
+      for (let attempt = 0; ; attempt++) {
+        try {
+          const value = await loader({ signal: controller.signal });
+          if (flights.get(key) === flight) store(key, value);
+          return value;
+        } catch (error) {
+          if (error?.name === "AbortError" || controller.signal.aborted || attempt >= maxRetries) throw error;
+          await sleep(baseRetryDelayMs * (2 ** attempt));
+          if (controller.signal.aborted) throw abortError();
+        }
+      }
+    })().finally(() => {
+      if (flights.get(key) === flight) flights.delete(key);
+    });
+    flights.set(key, flight);
+    return flight;
+  }
+
+  function waitFor(key, flight, signal) {
+    flight.waiters++;
+    return new Promise((resolve, reject) => {
+      let done = false;
+      const cleanup = () => signal?.removeEventListener("abort", onAbort);
+      const onAbort = () => {
+        if (done) return;
+        done = true;
+        cleanup();
+        flight.waiters--;
+        reject(abortError());
+        if (flight.waiters === 0) {
+          flight.controller.abort();
+          if (flights.get(key) === flight) flights.delete(key);
+        }
+      };
+      signal?.addEventListener("abort", onAbort, { once: true });
+      flight.promise.then(
+        (value) => {
+          if (done) return;
+          done = true;
+          cleanup();
+          resolve(value);
+        },
+        (error) => {
+          if (done) return;
+          done = true;
+          cleanup();
+          reject(error);
+        },
+      );
+    });
+  }
+
+  async function get(key, loader, { signal } = {}) {
+    if (signal?.aborted) throw abortError();
+    const entry = entries.get(key);
+    if (entry) {
+      const age = now() - entry.storedAt;
+      if (age < ttlMs) {
+        entries.delete(key);
+        entries.set(key, entry);
+        counters.hits++;
+        return entry.value;
+      }
+      if (age < ttlMs + staleWhileRevalidateMs) {
+        entries.delete(key);
+        entries.set(key, entry);
+        counters.staleHits++;
+        if (!flights.has(key)) launch(key, loader).promise.catch(() => {});
+        return entry.value;
+      }
+      entries.delete(key);
+    }
+
+    counters.misses++;
+    let flight = flights.get(key);
+    if (flight) counters.coalesced++;
+    else flight = launch(key, loader);
+    return waitFor(key, flight, signal);
+  }
+
+  return {
+    get,
+    invalidate(key) {
+      entries.delete(key);
+    },
+    clear() {
+      entries.clear();
+    },
+    stats() {
+      return { size: entries.size, ...counters };
+    },
+  };
+}
